import Foundation
import SwiftUI

/// English, Spanish and Portuguese (Brazil), chosen in Settings ("system" follows the phone: pt, es, else en). Generated from the Android strings: keep both apps the same.
final class I18n: ObservableObject {
    static let shared = I18n()
    @Published var choice: String = UserDefaults.standard.string(forKey: "lang") ?? "system" {
        didSet { UserDefaults.standard.set(choice, forKey: "lang") }
    }
    var lang: String {
        let l = choice != "system" ? choice : String((Locale.preferredLanguages.first ?? "en").prefix(2))
        return l == "es" || l == "pt" ? l : "en"
    }
}

func t(_ key: String, _ args: CustomStringConvertible...) -> String {
    var s = strings[key].map { x -> String in switch I18n.shared.lang { case "es": return x.1; case "pt": return x.2; default: return x.0 } } ?? key
    for (i, a) in args.enumerated() { s = s.replacingOccurrences(of: "{\(i)}", with: a.description) }
    return s
}

